style.css:
@-moz-document domain("instructure.com") {
/* Background of main content only */
  #main, .ic-app-main-content {
    background: #fceef5 !important;
  }

  /* Top navigation bar */
  .ic-app-header {
    background-color: #f7cce5 !important;
    border-bottom: 2px solid #f3b6d4 !important;
  }

  /* Left sidebar */
  .ic-app-course-nav {
    background-color: #f9d8eb !important;
  }

  .ic-app-course-nav-list-item {
    background-color: #fceef5 !important;
    border: 1px solid #f3b6d4 !important;
    border-radius: 10px !important;
    margin: 6px 0 !important;
  }

  .ic-app-course-nav-list-item:hover {
    background-color: #f7cce5 !important;
  }

  /* Buttons (Canvas-safe selectors only) */
  .Button, .btn, .ui-button {
    background-color: #f7cce5 !important;
    border: 2px solid #f3b6d4 !important;
    color: #5a4a4a !important;
    border-radius: 10px !important;
    transition: 0.2s ease;
  }

  .Button:hover, .btn:hover, .ui-button:hover {
    background-color: #f9d8eb !important;
    transform: scale(1.03);
  }

  /* Module cards */
  .ic-Module__title,
  .ic-Module,
  .ic-Module-item {
    background-color: #fff5fa !important;
    border: 1px solid #f3b6d4 !important;
    border-radius: 12px !important;
  }

  /* Assignment cards */
  .ic-Card {
    background-color: #fff5fa !important;
    border: 1px solid #f3b6d4 !important;
    border-radius: 12px !important;
  }

  /* Text inputs */
  input:not([type="checkbox"]),
  textarea {
    background-color: #fff0f7 !important;
    border: 2px solid #f3b6d4 !important;
    border-radius: 8px !important;
  }

  /* Links */
  a {
    color: #d86fa7 !important;
    font-weight: 600 !important;
  }

  a:hover {
    color: #b85c92 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #f3b6d4 !important;
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background-color: #d86fa7 !important;
  }
}
